ab_tests.py tools/combat-tests/grab-test-fixture.lua tools/combat-tests/validate_grab_assets.py tools/combat-tests/GrabAssetProbe.java tools/combat-tests/AnimationProbe.java tools/combat-tests/build_ground_heat_assets.py tools/combat-tests/extract_ground_heat_assets.py tools/combat-tests/validate_ground_heat_assets.py tools/combat-tests/calibrate_ground_contact.py tools/combat-tests/StyleFXProbe.java tools/combat-tests/validate_style_fx.py tools/combat-tests/NativeRushTimingProbe.java tools/combat-tests/validate_grab_alignment.py tools/combat-tests/build_rush_twohit_assets.py tools/combat-tests/validate_rush_twohit_assets.py tools/combat-tests/build_grab_escape_assets.py tools/combat-tests/extract_crate_heat_assets.py tools/combat-tests/retarget_crate_heat.py tools/combat-tests/build_crate_heat_assets.py tools/combat-tests/validate_grab_crate_assets.py tools/combat-tests/validate_event_bursts.py tools/combat-tests/build_low_health_tests.py tools/combat-tests/low-health-test-fixture.lua tools/combat-tests/LowHealthProbe.java tools/combat-tests/build_heat_presentation.py tools/combat-tests/build_heat_presentation_tests.py tools/combat-tests/heat-presentation-test-fixture.lua
    if ($LASTEXITCODE -ne 0) { throw 'git add failed.' }
    & git diff --cached --quiet
    if ($LASTEXITCODE -eq 1) {
        & git commit -m ("Release " + $tag)
        if ($LASTEXITCODE -ne 0) { throw 'git commit failed.' }
    } elseif ($LASTEXITCODE -ne 0) { throw 'Cannot inspect staged changes.' }
    & git branch -M main
    & git push -u origin main
    if ($LASTEXITCODE -ne 0) { throw 'git push failed.' }
    $revision = (& git rev-parse HEAD).Trim()
    & $GhPath release create $tag $archive --repo $Repo --target $revision --title $tag --notes-file $notes
    if ($LASTEXITCODE -ne 0) { throw 'GitHub release creation failed; the pushed commit and ZIP are preserved.' }
    & $GhPath release view $tag --repo $Repo --json url,tagName,assets
    if ($LASTEXITCODE -ne 0) { throw 'Cannot verify published release.' }
} finally { Pop-Location }
